1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { randomBytes } from "node:crypto";
5	import { z } from "zod";
6	import { db } from "./db";
7	import { requireUser } from "./auth";
8	import { requireArea } from "./rbac";
9	import { debitWallet, InsufficientBalanceError } from "./wallet";
10	import { addMonths } from "./billing-terms";
11	import { encryptSecret } from "./crypto-box";
12	import { currentPromo, promoPriceCents } from "./promotions";
13	import {
14	  mailcowConfigured,
15	  mcCreateDomain,
16	  mcDomainExists,
17	  mcCreateMailbox,
18	  mcDeleteMailbox,
19	  mcSetMailboxActive,
20	} from "./mailcow";
21	
22	/**
23	 * Business Email — mailbox hosting per registered domain.
24	 *
25	 * An `EmailPlan` is a pricing tier (N mailboxes, GB/mailbox, price, term). A
26	 * customer subscribes one of their own domains to a tier (`EmailSubscription`),
27	 * which debits the wallet, then manages individual `Mailbox` rows under it.
28	 *
29	 * Mail delivery runs through a self-hosted Mailcow server, reached via lib/mailcow.ts
30	 * (config from MAILCOW_API_URL / MAILCOW_API_KEY). Creating a Mailbox row records
31	 * intent (status PROVISIONING); we then attempt to provision the real mailbox on
32	 * Mailcow and flip the row to ACTIVE, or FAILED if the call errors. All Mailcow
33	 * calls are additive and failure-tolerant — a Mailcow outage never breaks the
34	 * order flow; the row persists and can be retried via retryMailboxProvision.
35	 *
36	 * This module owns:
37	 *   - orderEmailHosting (customer subscribe)
38	 *   - addMailbox / removeMailbox / retryMailboxProvision (customer mailbox management)
39	 *   - adminSaveEmailPlan / adminToggleEmailPlan / adminDeleteEmailPlan (CRUD)
40	 */
41	
42	type Result = { error?: string; ok?: boolean };
43	
44	/**
45	 * Provision (or re-provision) a mailbox on Mailcow. Never throws — records the
46	 * outcome on the Mailbox row (status ACTIVE on success, FAILED on error) and
47	 * returns it. When Mailcow isn't configured the row is left PROVISIONING so it
48	 * can be picked up once the integration is wired.
49	 */
50	async function provisionMailboxOnMailcow(mailbox: {
51	  id: string;
52	  address: string;
53	  quotaMB: number | null;
54	  subscription: { domainName: string };
55	}): Promise<"ACTIVE" | "FAILED" | "PROVISIONING"> {
56	  if (!mailcowConfigured()) return "PROVISIONING";
57	
58	  const [localPart] = mailbox.address.split("@");
59	  const domain = mailbox.subscription.domainName;
60	  const quotaMB = mailbox.quotaMB ?? 1024;
61	
62	  try {
63	    // Ensure the mail domain exists before adding the mailbox.
64	    if (!(await mcDomainExists(domain))) {
65	      // A concurrent create or pre-existing domain can still error here; ignore
66	      // and let the mailbox add be the real signal.
67	      await mcCreateDomain(domain).catch(() => {});
68	    }
69	
70	    const password = randomBytes(18).toString("base64url");
71	    await mcCreateMailbox({
72	      localPart,
73	      domain,
74	      name: mailbox.address,
75	      password,
76	      quotaMB,
77	    });
78	
79	    await db.mailbox.update({
80	      where: { id: mailbox.id },
81	      data: { status: "ACTIVE", passwordEnc: encryptSecret(password) },
82	    });
83	    return "ACTIVE";
84	  } catch (e) {
85	    await db.mailbox
86	      .update({ where: { id: mailbox.id }, data: { status: "FAILED" } })
87	      .catch(() => {});
88	    console.warn(`[mailcow] provisioning ${mailbox.address} failed:`, e);
89	    return "FAILED";
90	  }
91	}
92	
93	// ---------- Admin CRUD (billing area) ----------
94	
95	const planSchema = z.object({
96	  id: z.string().optional(),
97	  name: z.string().min(2).max(80),
98	  mailboxes: z.coerce.number().int().min(1).max(100000),
99	  storageGB: z.coerce.number().int().min(1).max(100000),
100	  priceCents: z.coerce.number().int().min(0).max(100000000),
101	  termMonths: z.coerce.number().int().min(1).max(36),
102	  sortOrder: z.coerce.number().int().min(0).max(100000),
103	});
104	
105	/** Create or update an EmailPlan tier. ADMIN/BILLING only, audit-logged. */
106	export async function adminSaveEmailPlan(
107	  prev: Result | undefined,
108	  formData: FormData,
109	): Promise<Result> {
110	  const admin = await requireArea("billing");
111	
112	  const parsed = planSchema.safeParse({
113	    id: formData.get("id") || undefined,
114	    name: formData.get("name"),
115	    mailboxes: formData.get("mailboxes"),
116	    storageGB: formData.get("storageGB"),
117	    priceCents: formData.get("priceCents"),
118	    termMonths: formData.get("termMonths"),
119	    sortOrder: formData.get("sortOrder") ?? 0,
120	  });
121	  if (!parsed.success) {
122	    return { error: parsed.error.issues[0]?.message ?? "Check the tier values." };
123	  }
124	  const d = parsed.data;
125	  const active = formData.get("active") === "on";
126	
127	  const data = {
128	    name: d.name.trim(),
129	    mailboxes: d.mailboxes,
130	    storageGB: d.storageGB,
131	    priceCents: d.priceCents,
132	    termMonths: d.termMonths,
133	    active,
134	    sortOrder: d.sortOrder,
135	  };
136	
137	  if (d.id) {
138	    const existing = await db.emailPlan.findUnique({ where: { id: d.id } });
139	    if (!existing) return { error: "Tier not found." };
140	    await db.emailPlan.update({ where: { id: d.id }, data });
141	  } else {
142	    await db.emailPlan.create({ data });
143	  }
144	
145	  await db.auditLog.create({
146	    data: {
147	      userId: admin.id,
148	      action: d.id ? "emailplan.update" : "emailplan.create",
149	      detail: `${data.name} — ${data.mailboxes} mbx / ${data.storageGB}GB (${(data.priceCents / 100).toFixed(2)}/${data.termMonths}mo)`,
150	    },
151	  });
152	  revalidatePath("/admin/email-plans");
153	  return { ok: true };
154	}
