156	/** Flip a tier's active flag. */
157	export async function adminToggleEmailPlan(id: string): Promise<void> {
158	  const admin = await requireArea("billing");
159	  const plan = await db.emailPlan.findUnique({ where: { id } });
160	  if (!plan) return;
161	  await db.emailPlan.update({ where: { id }, data: { active: !plan.active } });
162	  await db.auditLog.create({
163	    data: { userId: admin.id, action: "emailplan.toggle", detail: `${plan.name} → active=${!plan.active}` },
164	  });
165	  revalidatePath("/admin/email-plans");
166	}
