168	/** Delete a tier. Refused while subscriptions reference it. */
169	export async function adminDeleteEmailPlan(id: string): Promise<Result> {
170	  const admin = await requireArea("billing");
171	  const plan = await db.emailPlan.findUnique({
172	    where: { id },
173	    include: { _count: { select: { subscriptions: true } } },
174	  });
175	  if (!plan) return { error: "Tier not found." };
176	  if (plan._count.subscriptions > 0) {
177	    return {
178	      error: `Can't delete — ${plan._count.subscriptions} subscription(s) use this tier. Disable it instead.`,
179	    };
180	  }
181	  await db.emailPlan.delete({ where: { id } });
182	  await db.auditLog.create({
183	    data: { userId: admin.id, action: "emailplan.delete", detail: plan.name },
184	  });
185	  revalidatePath("/admin/email-plans");
186	  return { ok: true };
187	}
188	
189	// ---------- Customer ordering ----------
190	
191	/**
192	 * Subscribe one of the caller's registered domains to an email plan. Validates
193	 * domain ownership + plan availability, then atomically debits the wallet and
194	 * creates the EmailSubscription with an expiry set from the plan term.
195	 *
196	 * The subscription is created ACTIVE (billing-wise), but no mailboxes are
197	 * provisioned with a mail provider yet — that integration is pending, and the
198	 * UI surfaces every mailbox as "provisioning" until it lands.
199	 */
200	export async function orderEmailHosting(
201	  domainName: string,
202	  emailPlanId: string,
203	): Promise<Result> {
204	  const user = await requireUser();
205	
206	  const name = String(domainName ?? "").trim().toLowerCase();
207	  if (!name) return { error: "Choose a domain." };
208	
209	  // Ownership check — the domain must be registered to this user.
210	  const domain = await db.domain.findFirst({ where: { name, userId: user.id } });
211	  if (!domain) return { error: "That domain isn't in your account." };
212	
213	  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
214	  if (!plan || !plan.active) return { error: "That email plan isn't available." };
215	
216	  // One subscription per domain — refuse a duplicate.
217	  const dupe = await db.emailSubscription.findFirst({
218	    where: { userId: user.id, domainName: name, status: { not: "CANCELLED" } },
219	  });
220	  if (dupe) return { error: "This domain already has an email subscription." };
221	
222	  // Seasonal promo = HONEST intro discount on the FIRST term only. The renewal
223	  // path (worker/product-renewals.ts) bills plan.priceCents unchanged, so the
224	  // strikethrough shown on the pricing page is the real renewal price and this
225	  // discounted value is the real first-term price — displayed === charged.
226	  const promo = currentPromo(new Date());
227	  const chargeCents = promoPriceCents(plan.priceCents, promo);
228	  const promoNote = promo.discountPercent > 0 ? ` — ${promo.name} ${promo.discountPercent}% off first term` : "";
229	  if (user.balanceCents < chargeCents) {
230	    return { error: "Insufficient balance. Top up your wallet first." };
231	  }
232	
233	  try {
234	    await db.$transaction(async (tx) => {
235	      await debitWallet(tx, user.id, chargeCents);
236	      await tx.walletTransaction.create({
237	        data: {
238	          userId: user.id,
239	          amountCents: -chargeCents,
240	          description: `Business Email: ${plan.name} for ${name}${promoNote}`,
241	        },
242	      });
243	      await tx.emailSubscription.create({
244	        data: {
245	          userId: user.id,
246	          domainName: name,
247	          emailPlanId: plan.id,
248	          status: "ACTIVE",
249	          autoRenew: true,
250	          expiresAt: addMonths(new Date(), plan.termMonths),
251	        },
252	      });
253	    });
254	  } catch (e) {
255	    if (e instanceof InsufficientBalanceError) {
256	      return { error: "Insufficient balance. Top up your wallet first." };
257	    }
258	    throw e;
259	  }
260	
261	  await db.auditLog.create({
262	    data: {
263	      userId: user.id,
264	      action: "emailhosting.order",
265	      detail: `${name} plan=${plan.name}`,
266	    },
267	  });
268	  revalidatePath("/dashboard/email");
269	  return { ok: true };
270	}
271	
272	// Local-part of an email address: RFC-ish, conservative. No leading/trailing dot.
273	const localPartRe = /^[a-z0-9]+(?:[._-][a-z0-9]+)*$/;
274	
275	/**
276	 * Add a mailbox to a subscription the caller owns. Enforces the plan's mailbox
277	 * quota and address uniqueness within the subscription, records the intended
278	 * mailbox (status PROVISIONING), then attempts to provision it on Mailcow. A
279	 * Mailcow failure leaves the row as FAILED (retryable) but never fails the call.
280	 */
281	export async function addMailbox(subscriptionId: string, localPart: string): Promise<Result> {
282	  const user = await requireUser();
283	
284	  const sub = await db.emailSubscription.findUnique({
285	    where: { id: subscriptionId },
286	    include: { emailPlan: true, mailboxes: true },
287	  });
288	  if (!sub) return { error: "Subscription not found." };
289	  if (sub.userId !== user.id) return { error: "Not your subscription." };
290	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
291	
292	  const local = String(localPart ?? "").trim().toLowerCase();
293	  if (!localPartRe.test(local) || local.length > 64) {
294	    return { error: "Enter a valid mailbox name (letters, numbers, . _ - )." };
295	  }
296	
297	  const address = `${local}@${sub.domainName}`;
298	
299	  if (sub.mailboxes.length >= sub.emailPlan.mailboxes) {
300	    return {
301	      error: `Plan limit reached (${sub.emailPlan.mailboxes} mailbox${sub.emailPlan.mailboxes === 1 ? "" : "es"}). Upgrade to add more.`,
302	    };
303	  }
304	  if (sub.mailboxes.some((m) => m.address.toLowerCase() === address)) {
305	    return { error: "That address already exists." };
306	  }
307	
308	  // Per-mailbox quota (MB) comes from the plan tier's per-mailbox storage (GB).
309	  const quotaMB = sub.emailPlan.storageGB * 1024;
310	
311	  const mailbox = await db.mailbox.create({
312	    data: { subscriptionId: sub.id, address, quotaMB, status: "PROVISIONING" },
313	  });
314	
315	  await db.auditLog.create({
316	    data: { userId: user.id, action: "mailbox.add", detail: address },
317	  });
318	
319	  // Additive, failure-tolerant provisioning — never throws out of the flow.
320	  await provisionMailboxOnMailcow({
321	    id: mailbox.id,
322	    address: mailbox.address,
323	    quotaMB,
324	    subscription: { domainName: sub.domainName },
325	  });
326	
327	  revalidatePath("/dashboard/email");
328	  return { ok: true };
329	}
330	
331	/**
332	 * Re-attempt Mailcow provisioning for a mailbox stuck in PROVISIONING/FAILED.
333	 * Owner-only (the caller must own the mailbox via its subscription).
334	 */
335	export async function retryMailboxProvision(mailboxId: string): Promise<Result> {
336	  const user = await requireUser();
337	
338	  const mailbox = await db.mailbox.findUnique({
339	    where: { id: mailboxId },
340	    include: { subscription: true },
341	  });
342	  if (!mailbox) return { error: "Mailbox not found." };
343	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
344	  if (!mailcowConfigured()) return { error: "Mail server is not configured yet." };
345	
346	  await db.mailbox.update({ where: { id: mailbox.id }, data: { status: "PROVISIONING" } });
347	
348	  const status = await provisionMailboxOnMailcow({
349	    id: mailbox.id,
350	    address: mailbox.address,
351	    quotaMB: mailbox.quotaMB,
352	    subscription: { domainName: mailbox.subscription.domainName },
353	  });
354	
355	  await db.auditLog.create({
356	    data: { userId: user.id, action: "mailbox.retry", detail: `${mailbox.address} → ${status}` },
357	  });
358	  revalidatePath("/dashboard/email");
359	
360	  if (status === "FAILED") return { error: "Provisioning failed again — check the mail server." };
361	  return { ok: true };
362	}
363	
364	/** Remove a mailbox the caller owns (via its subscription). */
365	export async function removeMailbox(mailboxId: string): Promise<Result> {
366	  const user = await requireUser();
367	
368	  const mailbox = await db.mailbox.findUnique({
369	    where: { id: mailboxId },
370	    include: { subscription: true },
371	  });
372	  if (!mailbox) return { error: "Mailbox not found." };
373	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
374	
375	  // Best-effort delete on Mailcow before dropping the row — a mail-server outage
376	  // must not block the customer from removing the mailbox record.
377	  if (mailcowConfigured()) {
378	    await mcDeleteMailbox(mailbox.address).catch((e) => {
379	      console.warn(`[mailcow] delete ${mailbox.address} failed:`, e);
380	    });
381	  }
382	
383	  await db.mailbox.delete({ where: { id: mailbox.id } });
384	
385	  await db.auditLog.create({
386	    data: { userId: user.id, action: "mailbox.remove", detail: mailbox.address },
387	  });
388	  revalidatePath("/dashboard/email");
389	  return { ok: true };
390	}
391	
392	/**
393	 * Suspend or resume a mailbox the caller owns, mirroring the state onto Mailcow
394	 * (deactivate/activate). Owner-only, failure-tolerant on the Mailcow call.
395	 */
396	export async function setMailboxSuspended(mailboxId: string, suspended: boolean): Promise<Result> {
397	  const user = await requireUser();
398	
399	  const mailbox = await db.mailbox.findUnique({
400	    where: { id: mailboxId },
401	    include: { subscription: true },
402	  });
403	  if (!mailbox) return { error: "Mailbox not found." };
404	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
405	
406	  if (mailcowConfigured()) {
407	    await mcSetMailboxActive(mailbox.address, !suspended).catch((e) => {
408	      console.warn(`[mailcow] set active ${mailbox.address} failed:`, e);
409	    });
410	  }
411	
412	  await db.mailbox.update({
413	    where: { id: mailbox.id },
414	    data: { status: suspended ? "SUSPENDED" : "ACTIVE" },
415	  });
416	
417	  await db.auditLog.create({
418	    data: {
419	      userId: user.id,
420	      action: suspended ? "mailbox.suspend" : "mailbox.resume",
421	      detail: mailbox.address,
422	    },
423	  });
424	  revalidatePath("/dashboard/email");
425	  return { ok: true };
426	}
