1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { PageHeader, Badge } from "@/components/ui/primitives";
4	import {
5	  EmailHosting,
6	  type PlanOpt,
7	  type SubscriptionRow,
8	} from "@/components/customer/EmailHosting";
9	
10	export const dynamic = "force-dynamic";
11	
12	export default async function EmailHostingPage() {
13	  const user = await requireUser();
14	
15	  const [domains, plans, subscriptions] = await Promise.all([
16	    db.domain.findMany({
17	      where: { userId: user.id, status: "ACTIVE" },
18	      orderBy: { name: "asc" },
19	    }),
20	    db.emailPlan.findMany({
21	      where: { active: true },
22	      orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }],
23	    }),
24	    db.emailSubscription.findMany({
25	      where: { userId: user.id, status: { not: "CANCELLED" } },
26	      include: { emailPlan: true, mailboxes: { orderBy: { createdAt: "asc" } } },
27	      orderBy: { createdAt: "desc" },
28	    }),
29	  ]);
30	
31	  const planOpts: PlanOpt[] = plans.map((p) => ({
32	    id: p.id,
33	    name: p.name,
34	    mailboxes: p.mailboxes,
35	    storageGB: p.storageGB,
36	    priceCents: p.priceCents,
37	    termMonths: p.termMonths,
38	  }));
39	
40	  const subRows: SubscriptionRow[] = subscriptions.map((s) => ({
41	    id: s.id,
42	    domainName: s.domainName,
43	    status: s.status,
44	    planName: s.emailPlan.name,
45	    planMailboxes: s.emailPlan.mailboxes,
46	    planStorageGB: s.emailPlan.storageGB,
47	    expiresAt: s.expiresAt ? s.expiresAt.toISOString() : null,
48	    mailboxes: s.mailboxes.map((m) => ({
49	      id: m.id,
50	      address: m.address,
51	      createdAt: m.createdAt.toISOString(),
52	    })),
53	  }));
54	
55	  return (
56	    <div>
57	      <PageHeader
58	        title="Business Email"
59	        sub="Professional mailboxes on your own domain (you@yourdomain.com)."
60	      >
61	        <Badge tone="brand">{subRows.length} subscription{subRows.length === 1 ? "" : "s"}</Badge>
62	      </PageHeader>
63	
64	      <EmailHosting
65	        domains={domains.map((d) => d.name)}
66	        plans={planOpts}
67	        subscriptions={subRows}
68	        balanceCents={user.balanceCents}
69	      />
70	    </div>
71	  );
72	}
