187	// ---------- Analytics ----------
188	
189	export type MailStats = {
190	  configured: true;
191	  domains: number;
192	  mailboxes: number;
193	  postfix: {
194	    sampled: number;
195	    sent: number;
196	    deferred: number;
197	    bounced: number;
198	    rejected: number;
199	    other: number;
200	  };
201	  rspamd: {
202	    sampled: number;
203	    actions: Record<string, number>;
204	    spam: number; // reject + add header + rewrite subject
205	    clean: number; // no action + greylist / soft reject
206	  };
207	};
208	
209	function asArray(v: unknown): unknown[] {
210	  if (Array.isArray(v)) return v;
211	  if (v && typeof v === "object" && Array.isArray((v as { rows?: unknown[] }).rows)) {
212	    return (v as { rows: unknown[] }).rows;
213	  }
214	  return [];
215	}
216	
217	/**
218	 * Pull recent postfix + rspamd logs and domain/mailbox counts for the admin
219	 * deliverability view. Throws (MailcowError) if not configured or unreachable —
220	 * the admin page catches that and shows a graceful fallback.
221	 */
222	export async function mcStats(sample = 400): Promise<MailStats> {
223	  config(); // throws early with a clear message if not configured
224	
225	  const [domainsRaw, mailboxesRaw, postfixRaw, rspamdRaw] = await Promise.all([
226	    mcRequest("GET", "/get/domain/all").catch(() => []),
227	    mcRequest("GET", "/get/mailbox/all").catch(() => []),
228	    mcRequest("GET", `/get/logs/postfix/${sample}`).catch(() => []),
229	    mcRequest("GET", `/get/logs/rspamd-history/${sample}`).catch(() => []),
230	  ]);
231	
232	  const postfixLogs = asArray(postfixRaw);
233	  const postfix = { sampled: postfixLogs.length, sent: 0, deferred: 0, bounced: 0, rejected: 0, other: 0 };
234	  for (const entry of postfixLogs) {
235	    const msg = String(
236	      (entry as { message?: unknown })?.message ??
237	        (entry && typeof entry === "object" ? JSON.stringify(entry) : entry) ??
238	        "",
239	    ).toLowerCase();
240	    if (msg.includes("status=sent")) postfix.sent++;
241	    else if (msg.includes("status=deferred")) postfix.deferred++;
242	    else if (msg.includes("status=bounced")) postfix.bounced++;
243	    else if (msg.includes("reject:") || msg.includes("status=reject")) postfix.rejected++;
244	    else postfix.other++;
245	  }
246	
247	  const rspamdLogs = asArray(rspamdRaw);
248	  const actions: Record<string, number> = {};
249	  let spam = 0;
250	  let clean = 0;
251	  for (const entry of rspamdLogs) {
252	    const action = String((entry as { action?: unknown })?.action ?? "unknown").toLowerCase();
253	    actions[action] = (actions[action] ?? 0) + 1;
254	    if (action === "reject" || action === "add header" || action === "rewrite subject") spam++;
255	    else clean++;
256	  }
257	
258	  return {
259	    configured: true,
260	    domains: asArray(domainsRaw).length,
261	    mailboxes: asArray(mailboxesRaw).length,
262	    postfix,
263	    rspamd: { sampled: rspamdLogs.length, actions, spam, clean },
264	  };
265	}
