// ---------- DKIM ----------

/**
 * Fetch the DKIM public-key TXT value for a domain from Mailcow
 * (`GET /api/v1/get/dkim/<domain>`). Mailcow returns an object carrying the
 * ready-to-publish TXT in `dkim_txt` (selector `dkim`). Returns the TXT string,
 * or null when the domain has no DKIM key yet or the shape is unexpected.
 *
 * Throws MailcowError only when the integration is unreachable/errors — callers
 * that must stay tolerant wrap this in try/catch.
 */
export async function mcGetDkim(domain: string): Promise<string | null> {
  const res = await mcRequest("GET", `/get/dkim/${encodeURIComponent(domain)}`);
  if (!res || typeof res !== "object") return null;
  // Mailcow returns {} for a domain with no key configured.
  const txt = (res as { dkim_txt?: unknown }).dkim_txt;
  if (typeof txt === "string" && txt.trim()) return txt.trim();
  return null;
}

