/**
 * Mail-platform DNS constants. Customers with a domain registered ELSEWHERE
 * publish these at their registrar so mail flows through the Nxeon mail server;
 * customers whose domain is inside Nxeon have this managed for them.
 */
const MAIL_HOST = "mail.nxeon.cloud";
const MAIL_MX_PRIORITY = 10;
const SPF_VALUE = "v=spf1 include:nxeon.cloud ~all";
const DMARC_VALUE = "v=DMARC1; p=none; rua=mailto:dmarc@nxeon.cloud";
const DKIM_SELECTOR = "dkim";

// A syntactically valid registrable domain (labels, no scheme, no trailing dot).
const domainRe =
  /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;

export type DnsRecord = {
  type: "TXT" | "MX";
  label: string; // human label for the row
  host: string; // record host / name
  value: string;
  priority?: number;
  note?: string;
};

