// ---------- External-domain DNS setup + verification ----------

/**
 * Return the DNS records a customer must publish at their registrar for an
 * EXTERNAL domain so mail flows through the Nxeon mail server, plus the
 * ownership-verification record. Ownership-checked (caller must own the sub).
 *
 * The DKIM record is fetched from Mailcow (`mcGetDkim`) and cached in
 * `dkimRecord`; when Mailcow isn't configured (or has no key yet) a placeholder
 * note is returned so the panel still renders.
 */
export async function getEmailDnsRecords(
  subscriptionId: string,
): Promise<{ error?: string; records?: DnsRecord[]; verified?: boolean; external?: boolean }> {
  const user = await requireUser();

  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
  if (!sub) return { error: "Subscription not found." };
  if (sub.userId !== user.id) return { error: "Not your subscription." };

  const domain = sub.domainName;

  // Resolve the DKIM TXT: prefer the cached value, else fetch + cache from Mailcow.
  let dkimTxt = sub.dkimRecord ?? null;
  if (!dkimTxt && mailcowConfigured()) {
    try {
      // Ensure the mail domain exists so Mailcow has generated a DKIM key.
      if (!(await mcDomainExists(domain))) {
        await mcCreateDomain(domain).catch(() => {});
      }
      dkimTxt = await mcGetDkim(domain);
      if (dkimTxt) {
        await db.emailSubscription
          .update({ where: { id: sub.id }, data: { dkimRecord: dkimTxt } })
          .catch(() => {});
      }
    } catch (e) {
      console.warn(`[mailcow] get dkim ${domain} failed:`, e);
    }
  }

  const records: DnsRecord[] = [
    {
      type: "TXT",
      label: "Ownership verification",
      host: `_nxeon-verify.${domain}`,
      value: `nxeon-verify=${sub.verifyToken ?? ""}`,
      note: "Proves you control this domain. Required before mail is enabled.",
    },
    {
      type: "MX",
      label: "Mail routing (MX)",
      host: domain,
      value: MAIL_HOST,
      priority: MAIL_MX_PRIORITY,
    },
    {
      type: "TXT",
      label: "SPF",
      host: domain,
      value: SPF_VALUE,
      note: "Authorizes the Nxeon mail server to send for your domain.",
    },
    {
      type: "TXT",
      label: "DKIM",
      host: `${DKIM_SELECTOR}._domainkey.${domain}`,
      value: dkimTxt ?? "",
      note: dkimTxt
        ? undefined
        : "DKIM key is being generated on the mail server — refresh this page shortly to see the value.",
    },
    {
      type: "TXT",
      label: "DMARC",
      host: `_dmarc.${domain}`,
      value: DMARC_VALUE,
      note: "Reporting policy for messages that fail SPF/DKIM.",
    },
  ];

  return { records, verified: sub.verified, external: sub.external };
}

/**
 * Verify that an EXTERNAL domain's owner has published our verification record.
 * Resolves the `_nxeon-verify` TXT via DNS and confirms it contains
 * `nxeon-verify=<verifyToken>`; the MX pointing at the mail host is accepted as
 * corroboration. The result is derived entirely server-side from live DNS —
 * client input never decides the outcome. Rate-limited per user + subscription.
 */
export async function verifyEmailDomain(subscriptionId: string): Promise<Result> {
  const user = await requireUser();

  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
  if (!sub) return { error: "Subscription not found." };
  if (sub.userId !== user.id) return { error: "Not your subscription." };
  if (!sub.external) return { error: "This domain is managed by Nxeon — no verification needed." };
  if (sub.verified) return { ok: true };
  if (!sub.verifyToken) return { error: "No verification token on this subscription." };

  const rl = checkRateLimit(`email-verify:${user.id}:${sub.id}`, {
    max: 6,
    windowMs: 60_000,
  });
  if (!rl.ok) {
    return { error: `Too many verification attempts. Try again in ${rl.retryAfterSec}s.` };
  }

  const domain = sub.domainName;
  const expected = `nxeon-verify=${sub.verifyToken}`;

  // Primary signal: the verification TXT record must contain our exact token.
  let tokenFound = false;
  try {
    const txt = await resolveTxt(`_nxeon-verify.${domain}`);
    // Each record may be split into multiple strings — join per-record chunks.
    tokenFound = txt.some((chunks) => chunks.join("").trim() === expected);
  } catch {
    tokenFound = false;
  }

  // Corroboration: MX pointing at the mail host (does not substitute for the token).
  let mxOk = false;
  try {
    const mx = await resolveMx(domain);
    mxOk = mx.some((r) => r.exchange.replace(/\.$/, "").toLowerCase() === MAIL_HOST);
  } catch {
    mxOk = false;
  }

  if (!tokenFound) {
    return {
      error: mxOk
        ? "MX is set, but the _nxeon-verify TXT record isn't visible yet. DNS can take a few minutes to propagate."
        : "Verification record not found yet. Add the _nxeon-verify TXT record and try again (DNS can take a few minutes).",
    };
  }

  await db.emailSubscription.update({
    where: { id: sub.id },
    data: { verified: true, verifiedAt: new Date() },
  });

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "emailhosting.verify",
      detail: `${domain}${mxOk ? " (MX + TXT)" : " (TXT)"}`,
    },
  });
  revalidatePath("/dashboard/email");
  return { ok: true };
}

