"use client";

import { useState, useTransition } from "react";
import { Badge } from "@/components/ui/primitives";
import { getEmailDnsRecords, verifyEmailDomain } from "@/lib/actions-email-hosting";

type DnsRecord = {
  type: "TXT" | "MX";
  label: string;
  host: string;
  value: string;
  priority?: number;
  note?: string;
};

/** Copy-to-clipboard button for a DNS field value. */
function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  if (!text) return null;
  return (
    <button
      type="button"
      className="btn-secondary shrink-0 px-2 py-1 text-xs"
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(text);
          setCopied(true);
          setTimeout(() => setCopied(false), 1500);
        } catch {
          /* clipboard blocked — no-op */
        }
      }}
    >
      {copied ? "Copied" : "Copy"}
    </button>
  );
}

function Field({ label, value }: { label: string; value: string }) {
  return (
    <div className="min-w-0">
      <div className="text-[11px] uppercase tracking-wide text-slate-500">{label}</div>
      <div className="flex items-center gap-2">
        <code className="min-w-0 flex-1 truncate rounded bg-white/[0.04] px-2 py-1 font-mono text-xs text-slate-200">
          {value || "—"}
        </code>
        <CopyButton text={value} />
      </div>
    </div>
  );
}

/**
 * "Finish setup" panel for an EXTERNAL, unverified email subscription. Lazily
 * loads the DNS records (server-side, ownership-checked), renders each with copy
 * buttons, and runs DNS verification. The verified result is decided entirely by
 * the server action — this component only reflects it.
 */
export function EmailDnsSetup({
  subscriptionId,
  domainName,
  verified: initialVerified,
}: {
  subscriptionId: string;
  domainName: string;
  verified: boolean;
}) {
  const [records, setRecords] = useState<DnsRecord[] | null>(null);
  const [verified, setVerified] = useState(initialVerified);
  const [error, setError] = useState<string | null>(null);
  const [status, setStatus] = useState<string | null>(null);
  const [loading, startLoad] = useTransition();
  const [verifying, startVerify] = useTransition();
  const [open, setOpen] = useState(false);

  function load() {
    setError(null);
    startLoad(async () => {
      const res = await getEmailDnsRecords(subscriptionId);
      if (res?.error) {
        setError(res.error);
        return;
      }
      setRecords(res.records ?? []);
      if (typeof res.verified === "boolean") setVerified(res.verified);
      setOpen(true);
    });
  }

  function verify() {
    setError(null);
    setStatus(null);
    startVerify(async () => {
      const res = await verifyEmailDomain(subscriptionId);
      if (res?.error) {
        setError(res.error);
      } else if (res?.ok) {
        setVerified(true);
        setStatus("DNS verified — mail is now enabled for this domain.");
      }
    });
  }

  if (verified) {
    return (
      <div className="mt-3 flex flex-wrap items-center gap-2 rounded-lg border border-emerald-500/30 bg-emerald-500/[0.08] px-3 py-2 text-sm text-emerald-300">
        <Badge tone="green">Verified</Badge>
        DNS is set up for <span className="font-mono">{domainName}</span> — mail is enabled.
      </div>
    );
  }

  return (
    <div className="mt-3 rounded-lg border border-amber-500/30 bg-amber-500/[0.06] p-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-sm font-semibold text-white">
            Finish setup — add these DNS records at your registrar
          </span>
          <Badge tone="amber">Verification required</Badge>
        </div>
        {!open && (
          <button className="btn-secondary py-1 text-sm" onClick={load} disabled={loading}>
            {loading ? "Loading…" : "Show DNS records"}
          </button>
        )}
      </div>

      <p className="mt-2 text-xs text-slate-300">
        <span className="font-mono">{domainName}</span> is registered outside Nxeon. Mail won&apos;t
        flow until you add these records at your DNS provider and verification succeeds. Mailboxes you
        create now are saved and go live once verified.
      </p>

      {error && (
        <div className="mt-2 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-400">
          {error}
        </div>
      )}
      {status && (
        <div className="mt-2 rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-xs text-emerald-300">
          {status}
        </div>
      )}

      {open && records && (
        <div className="mt-3 space-y-2">
          {records.map((r) => (
            <div
              key={`${r.type}-${r.host}-${r.label}`}
              className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-3"
            >
              <div className="mb-2 flex flex-wrap items-center gap-2">
                <Badge tone="slate">{r.type}</Badge>
                <span className="text-sm font-medium text-slate-200">{r.label}</span>
                {typeof r.priority === "number" && (
                  <span className="text-xs text-slate-500">priority {r.priority}</span>
                )}
              </div>
              <div className="grid gap-2 sm:grid-cols-2">
                <Field label="Host / Name" value={r.host} />
                <Field label="Value" value={r.value} />
              </div>
              {r.note && <p className="mt-2 text-xs text-slate-500">{r.note}</p>}
            </div>
          ))}

          <div className="flex flex-wrap items-center gap-3 pt-1">
            <button className="btn-primary py-1.5 text-sm" onClick={verify} disabled={verifying}>
              {verifying ? "Checking DNS…" : "Verify DNS"}
            </button>
            <span className="text-xs text-slate-500">
              We look up the records live — this can take a few minutes after you add them.
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

