                <option key={d} value={d} />
              ))}
            </datalist>
            <p className="mt-1 text-xs text-slate-500">
              {isExternal
                ? "Registered elsewhere — you'll add DNS records and verify after ordering."
                : "In your account — DNS is configured for you."}
            </p>
          </div>
          <div>
            <label className="label">Plan</label>
            <select className="input" value={planId} onChange={(e) => setPlanId(e.target.value)}>
              {plans.map((p) => (
                <option key={p.id} value={p.id}>
                  {p.name} — {p.mailboxes} mailbox{p.mailboxes === 1 ? "" : "es"} · {p.storageGB}GB ·{" "}
                  {fmtMoney(p.priceCents)}
                  {p.termMonths > 1 ? `/${p.termMonths}mo` : "/mo"}
                </option>
              ))}
            </select>
          </div>
        </div>

        {selected && (
          <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-white/[0.06] px-3 py-2 text-sm">
            <span className="text-slate-300">
              {selected.mailboxes} mailbox{selected.mailboxes === 1 ? "" : "es"} · {selected.storageGB} GB each
            </span>
            <span className="text-white">
              {fmtMoney(selected.priceCents)}
              {selected.termMonths > 1 ? ` / ${selected.termMonths} mo` : " / mo"}
            </span>
          </div>
        )}

        <div className="flex flex-wrap items-center justify-between gap-3">
          <span className="text-xs text-slate-500">
            Wallet balance: <span className="text-slate-300">{fmtMoney(balanceCents)}</span>
          </span>
          <button className="btn-primary" onClick={submit} disabled={pending || !domain.trim()}>
            {pending ? "Ordering…" : "Order email hosting"}
          </button>
        </div>
      </div>
    </section>
  );
}

